// CreateRule creates a rule
func (s *Server) CreateRule(ctx context.Context, req *flipt.CreateRuleRequest) (*flipt.Rule, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.SegmentKey == "" {
		return nil, emptyFieldError("segmentKey")
	}
	if req.Rank <= 0 {
