func TestEvaluatorComparisonNormalization(t *testing.T) {
	assert.True(t, matchesString(constraint{Operator: "EQ", Value: " bar "}, " bar "))
	assert.True(t, matchesString(constraint{Operator: "PREFIX", Value: " ba "}, " bar "))
	assert.True(t, matchesString(constraint{Operator: "SuFfIx", Value: " ar "}, " bar "))
	assert.True(t, matchesString(constraint{Operator: "PRESENT"}, " value "))
	assert.True(t, matchesString(constraint{Operator: "NOTPRESENT"}, " "))
	assert.NoError(t, validate(constraint{Property: "x", Operator: "TRUE"}))
	assert.Contains(t, noValueOperators, opTrue)
	assert.Contains(t, noValueOperators, opFalse)

	match, err := matchesNumber(constraint{Operator: "LtE", Value: " 2.5 "}, " 2.5 ")
	require.NoError(t, err)
	assert.True(t, match)
	_, err = matchesNumber(constraint{Operator: "eq", Value: "2"}, "not-a-number")
	require.Error(t, err)
	_, err = matchesNumber(constraint{Operator: "eq", Value: "2"}, "NaN")
	require.Error(t, err)

	match, err = matchesBool(constraint{Operator: "TrUe"}, " true ")
	require.NoError(t, err)
	assert.True(t, match)
	_, err = matchesBool(constraint{Operator: "false"}, "maybe")
	require.Error(t, err)
}

